function validate([names]) {
  if (!Array.isArray(names) || names.length < 1 || names.length > 50000) return 'names needs 1 to 5 * 10^4 entries.';
  if (names.some(s => typeof s !== 'string' || s.length < 1 || s.length > 20)) return 'Each name has 1 to 20 characters.';
  if (names.some(s => !/^[a-z0-9()]+$/.test(s))) return 'Names use only lowercase letters, digits and round brackets.';
  return null;
}

