function getFolderNames(names) {
  const nextSuffix = new Map();
  const result = [];
  for (const name of names) {
    if (!nextSuffix.has(name)) {
      nextSuffix.set(name, 1);
      result.push(name);
      continue;
    }
    let k = nextSuffix.get(name);
    while (nextSuffix.has(name + '(' + k + ')')) {
      k++;
    }
    const unique = name + '(' + k + ')';
    nextSuffix.set(name, k + 1);
    nextSuffix.set(unique, 1);
    result.push(unique);
  }
  return result;
}

