function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const pick = list => list[Math.floor(rand() * list.length)];
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = (lo, hi) => Array.from({ length: int(lo, hi) }, () => letters[Math.floor(rand() * 26)]).join('');
  const large = size === 'large';
  const n = large ? int(1800, 2000) : int(1, 8);
  const bases = large ? Array.from({ length: int(1, 30) }, () => word(1, 10)) : ['a', 'b', 'ab', '0', '(1)'].slice(0, int(1, 5));
  const names = [];
  for (let i = 0; i < n; i++) {
    const base = pick(bases);
    const roll = rand();
    let name = base;
    if (roll < 0.25) name = `${base}(${int(0, large ? 300 : 3)})`;
    else if (roll < 0.3) name = `${base}(${int(1, 2)})(${int(1, 2)})`;
    else if (roll < 0.35 && names.length) name = pick(names);
    names.push(name.slice(0, 20));
  }
  return [names];
}
